class SendMessageDialogController{constructor($scope,$mdDialog,DispatchData,toastrService,selectedCourierId){this.$scope=$scope;this.$mdDialog=$mdDialog;this.DispatchData=DispatchData;this.toastrService=toastrService;this.selectedCourierId=selectedCourierId;this.message=""}async submit(message){try{console.log("Message",message);console.log("Courier",this.selectedCourierId);await this.DispatchData.sendSMS(this.selectedCourierId,ContactID,FirstName,message);this.toastrService.showSuccessToast("Message Sent!")}catch(error){this.toastrService.showErrorToast(error.message)}finally{this.$mdDialog.hide()}}cancel(){this.$mdDialog.cancel()}}